import {inspectCastleFootprint} from './castle-footprint.js';
import * as T from '../vendor/three.module.js';
export function castlePorts(world,team){
 const castle=world.castles[team],cells=[],layout=[];castle.updateMatrixWorld(true);castle.traverse(g=>{for(let o=g;o;o=o.parent)if(!o.visible)return;if(g.userData.cell&&!g.userData.solidTerrace)layout.push({...g.userData.cell});if(g.userData.cell?.type!=='deck'||g.userData.solidTerrace)return;for(let p=g;p;p=p.parent)if(!p.visible)return;cells.push({mesh:g,...g.userData.cell});});
 const remaining=new Set(cells),clusters=[];
 while(remaining.size){const first=remaining.values().next().value,cluster=[first];remaining.delete(first);for(let i=0;i<cluster.length;i++)for(const c of remaining)if(c.layer===first.layer&&Math.abs(c.x-cluster[i].x)+Math.abs(c.z-cluster[i].z)===1){remaining.delete(c);cluster.push(c);}clusters.push(cluster);}
 if(!cells.length){const p=world.pads[team],sign=team?-1:1;return [true,false].map((big,i)=>({id:'legacy-'+team+'-'+i,big,length:big?32:16,approach:new T.Vector3(p.x+sign*26,p.y,0),home:new T.Vector3(p.x+sign*32,p.y-3.2,big?-27:20),angle:0}));}
 return clusters.filter(group=>inspectCastleFootprint(layout).ports.some(p=>p.attached&&p.clear&&p.cells.some(q=>q.x===group[0].x&&q.z===group[0].z&&q.layer===group[0].layer))).slice(0,8).map((cells,i)=>{const points=cells.map(c=>c.mesh.getWorldPosition(new T.Vector3())),centre=points.reduce((a,p)=>a.add(p),new T.Vector3()).multiplyScalar(1/points.length),base=castle.getWorldPosition(new T.Vector3()),delta=centre.clone().sub(base),direction=new T.Vector3(...[[0,0,-1],[-1,0,0],[0,0,1],[1,0,0]][cells[0].rotation||0]).transformDirection(castle.matrixWorld),end=points.sort((a,b)=>b.dot(direction)-a.dot(direction))[0].clone().addScaledVector(direction,2.5),big=cells.length>=3,approach=end.clone();return {id:'deck-'+team+'-'+i,big,length:cells.length*8,approach,home:end.clone().addScaledVector(direction,big?28:18).add(new T.Vector3(0,-3.2,0)),angle:Math.atan2(direction.x,direction.z)};});
}
